const moduleCopy={free:['Pulsuz','Ücretsiz','Бесплатно','Free','مجاني'],premium:['Premium','Premium','Премиум','Premium','بريميوم'],closed:['Bağlı','Kapalı','Закрыто','Closed','مغلق'],trial:['Sınaq','Deneme','Пробный период','Trial','تجريبي'],unavailable:['Bölmə müvəqqəti bağlıdır.','Bölüm geçici olarak kapalı.','Раздел временно закрыт.','This section is temporarily closed.','هذا القسم مغلق مؤقتًا.'],connection:['Giriş ayarlarını yeniləmək üçün internetə qoşulun.','Erişim ayarlarını yenilemek için internete bağlanın.','Подключитесь к интернету для обновления доступа.','Connect to update access settings.','اتصل بالإنترنت لتحديث إعدادات الوصول.'],until:['Sınaq bitir','Deneme bitişi','Пробный период до','Trial ends','نهاية التجربة'],loading:['Giriş ayarları yoxlanılır…','Erişim ayarları kontrol ediliyor…','Проверка доступа…','Checking access…','جارٍ التحقق من الوصول…']};
function mc(k){return moduleCopy[k]?.[['az','tr','ru','en','ar'].indexOf(lang())]||moduleCopy[k]?.[0]||k}
const managedModules=['collection','quiz','ramadan'];
let modulePolicyState={rows:[],ready:false,loading:false,until:0,serverTime:0,received:0,error:false};
function policyClock(){return typeof performance!=='undefined'?performance.now():Date.now()}
function moduleTitle(id){return id==='collection'?ux('myDuas'):id==='quiz'?ux('quiz'):rm('ramadan')}
function moduleDecision(id){const s=modulePolicyState,row=s.rows.find(x=>x.module===id);if(!s.ready||!row||policyClock()>=s.until)return 'offline';if(row.mode==='closed')return 'closed';if(row.mode==='free')return 'free';if(row.mode==='trial'&&policyClock()<row.deadline)return 'trial';return 'premium'}
function moduleCanOpen(id){const d=moduleDecision(id);return d==='free'||d==='trial'||(d==='premium'&&premiumState.premium===true)}
function applyModulePolicies(data,started=policyClock()){if(!data||!Array.isArray(data.modules)||data.modules.length!==3||!Number.isFinite(Date.parse(data.server_time)))throw Error('Invalid policies');const ids=new Set(),serverTime=Date.parse(data.server_time);const rows=data.modules.map(r=>{if(!managedModules.includes(r.module)||ids.has(r.module)||!['free','premium','closed','trial'].includes(r.mode)||!Number.isInteger(r.revision)||r.revision<1||(r.mode==='trial'&&!Number.isFinite(Date.parse(r.trial_until))))throw Error('Invalid policy');ids.add(r.module);return {...r,deadline:started+Math.max(0,Date.parse(r.trial_until)-serverTime)}});modulePolicyState={rows,ready:true,loading:false,error:false,until:started+Math.max(1,Math.min(90,Number(data.lease_seconds)||1))*1000,serverTime,received:started}}
function moduleSignature(){return managedModules.map(id=>id+':'+moduleDecision(id)+':'+(modulePolicyState.rows.find(r=>r.module===id)?.revision||0)).join('|')}
function paintModuleBadges(){for(const e of document.querySelectorAll('[data-premium-module]')){const decision=moduleDecision(e.getAttribute('data-premium-module'));e.setAttribute('data-access-label',decision==='premium'?'PRO':decision==='offline'?'…':mc(decision))}}
function refreshManagedPage(before){const current=location.hash.slice(1).split('/')[0],id=current==='fasting'?'ramadan':current;if(managedModules.includes(id)&&before!==moduleSignature()){if(!moduleCanOpen(id)&&document.querySelector('.modal-layer'))closeContentModal();render()}if(current==='cloudadmin'&&!document.activeElement?.closest?.('[data-module-policy]')&&before!==moduleSignature())render()}
async function loadModulePolicies(){if(modulePolicyState.loading)return;const started=policyClock(),before=moduleSignature();modulePolicyState.loading=true;try{applyModulePolicies(await cloudRequest('/rest/v1/rpc/shams_module_access',{}),started)}catch{modulePolicyState.loading=false;modulePolicyState.error=true}refreshManagedPage(before);paintModuleBadges();if(!modulePolicyState.ready&&managedModules.includes(location.hash.slice(1).split('/')[0]))render()}
const premiumRouteBeforePolicy=premiumRoute;
premiumRoute=function(id,page){const decision=moduleDecision(id);if(moduleCanOpen(id)){const r=modulePolicyState.rows.find(r=>r.module===id);return (decision==='trial'?`<p class="module-trial-notice" data-localized="true">${mc('until')}: ${esc(new Date(r.trial_until).toLocaleString(lang()))}</p>`:'')+page()}if(decision==='premium')return premiumRouteBeforePolicy(id,page);return head(moduleTitle(id),'')+`<section class="card premium-lock" data-localized="true">${uiIcon(decision==='closed'?'lock':'globe')}<p>${mc(decision==='closed'?'unavailable':modulePolicyState.loading?'loading':'connection')}</p><button class="secondarybtn" onclick="loadModulePolicies()">${uiIcon('refresh')}${pw('retry')}</button></section>`};
function modulePolicyAdminHTML(){if(!cloudState.admin)return '';return `<section class="card module-policy-admin"><h2>${uiIcon('lock')} Premium bölmələr</h2><p class="notice policy-help">Ayarlar APK və veb üçün ortaqdır. Dəyişiklik internet olduqda təxminən 30 saniyədə görünür. Sınaq hamı üçün açılır; vaxt bitdikdə bölmə Premium olur. Ödənişli abunə statusu dəyişmir.</p>${managedModules.map(id=>{const row=modulePolicyState.rows.find(r=>r.module===id);return row?`<form data-module-policy="${id}" onsubmit="event.preventDefault();saveModulePolicy(this)"><h3>${moduleTitle(id)}</h3><input type="hidden" name="module" value="${id}"><input type="hidden" name="revision" value="${row.revision}"><label>Rejim<select name="mode" aria-label="${moduleTitle(id)} rejimi">${['free','premium','closed','trial'].map(mode=>`<option value="${mode}" ${row.mode===mode?'selected':''}>${mc(mode)}</option>`).join('')}</select></label><label>Sınaq müddəti (gün)<input name="days" type="number" min="1" max="365" value="1" required></label><p class="notice">Hazırkı giriş: ${mc(moduleDecision(id)==='offline'?'premium':moduleDecision(id))}${row.mode==='trial'?' · '+mc('until')+': '+esc(new Date(row.trial_until).toLocaleString(lang())):''}</p><button class="goldbtn">${cw('save')}</button><p class="policy-save-status" role="status"></p></form>`:`<p>${moduleTitle(id)} · ${mc('loading')}</p>`}).join('')}<button class="textbtn" onclick="loadModulePolicies()">${uiIcon('refresh')}Ayarları yenilə</button></section>`}
async function saveModulePolicy(form){if(!cloudState.admin)return;const f=new FormData(form),button=form.querySelector('button'),status=form.querySelector('[role=status]');button.disabled=true;status.textContent='';try{const data=await cloudRequest('/rest/v1/rpc/shams_admin_module',{p_module:String(f.get('module')),p_mode:String(f.get('mode')),p_days:Number(f.get('days')),p_revision:Number(f.get('revision'))});applyModulePolicies(data);await loadModulePolicies();await loadCloudAdmin();toast(cw('saved'))}catch{status.textContent='Saxlanmadı. Bağlantını və admin girişini yoxlayın; ayarlar başqa pəncərədə dəyişibsə yeniləyin.'}finally{button.disabled=false}}
function initializeModuleAccess(){const base=cloudAdminPage;cloudAdminPage=function(){const html=base();return cloudState.admin?html.replace('<div class="module-actions">',modulePolicyAdminHTML()+'<div class="module-actions">'):html};setTimeout(loadModulePolicies,0);setInterval(loadModulePolicies,30000);let previous='';setInterval(()=>{const key=moduleSignature();if(previous&&key!==previous)refreshManagedPage(previous);previous=key},1000);window.addEventListener('focus',loadModulePolicies);document.addEventListener('visibilitychange',()=>{if(!document.hidden)loadModulePolicies()})}
